import React, { useEffect } from 'react';
import { useNavigate } from 'react-router-dom';
import { exchangeToken } from '../services/api'; // Ensure this is correct

const SpotifyCallback = () => {
  const navigate = useNavigate();

  useEffect(() => {
    // Extract the code from the URL
    const params = new URLSearchParams(window.location.search);
    const code = params.get('code');

    const handleSpotifyCallback = async () => {
      try {
        const response = await exchangeToken(code); // Send code to the backend
        console.log('Received tokens:', response);

        // Save tokens in local storage or state as needed
        localStorage.setItem('accessToken', response.access_token);
        localStorage.setItem('refreshToken', response.refresh_token);

        // Redirect to the search page or wherever you want
        navigate('/');
      } catch (error) {
        console.error('Error exchanging code for token:', error);
      }
    };

    if (code) {
      handleSpotifyCallback();
    } else {
      console.error('No code found in the URL');
    }
  }, [navigate]);

  return <div>Processing Spotify authorization...</div>;
};

export default SpotifyCallback;
